// CheckCircuitBreaker v1.0

//const FAILURE_THRESHOLD = 5;
const TIMEOUT_MS = 60000; 
//const HALF_OPEN_TIMEOUT_MS = 30000;
const sheetData = $input.first().json;

const circuitState = {
  state: sheetData.state || 'closed',
  failureCount: Number(sheetData.failureCount) || 0,
  lastFailureTime: sheetData.lastFailureTime || null,
  openedAt: sheetData.openedAt || null,
  succesCount: sheetData.succesCount || 0
};

const mail = $('llegada Mail').first().json;

const now = Date.now();
if (circuitState.state === 'open') { //si el circuitBreaker está abierto
  const timeSinceOpen = now - Number(circuitState.openedAt);
  if (timeSinceOpen > TIMEOUT_MS) { //ya hace un minuto que fue abierto, pruebo cerrarlo de a poco
    console.log('🔄 Circuit Breaker: Transitioning to HALF_OPEN');
    circuitState.state = 'half_open'; //primero lo dejo en half-open
    circuitState.successCount = 0; //inicio el contador 
  } 
  else {
    const remainingMs = TIMEOUT_MS - timeSinceOpen;
    console.log(`🔴 Circuit Breaker OPEN - Reintentar en ${Math.ceil(remainingMs/1000)}s`); //si falta para el minuto
    return [{
      json: {
        circuitOpen: true,
        circuitState: 'open',
        retryAfterMs: remainingMs,
        message: 'Circuit breaker abierto - API temporalmente no disponible',
        useFallback: true,
        mail,
        _circuitStateToSave: circuitState //como uso un sheets de base de datos, la carga tiene que ser en un nodo próximo, no acá, por eso guardo el estado en un json que le pasaré más adelante. 
      }
    }];
  }
}

//si está cerrado o half open
console.log(`✅ Circuit Breaker ${circuitState.state.toUpperCase()} - Permitiendo requests`); 

return [{
  json: {
    circuitOpen: false,
    circuitState: circuitState.state,
    mail,
    canProceed: true,
    _circuitStateToSave:circuitState
  }
}];

// ParseAIResponse v2.0
// Parsea respuesta de OpenAI con manejo robusto de errores
// Función para actualizar circuit breaker

const FAILURE_THRESHOLD = 5;

const prevCircuitState = $('consultar CircuitState').first().json._circuitStateToSave
const circuitState= { //normalizo los valores del estado previo 
  state:prevCircuitState.state || 'closed',
  failureCount: Number(prevCircuitState.failureCount) || 0,
  lastFailureTime: prevCircuitState.lastFailureTime || null,
  openedAt: prevCircuitState.openedAt || null,
  successCount: Number(prevCircuitState.succesCount) || 0
};

const aiResponse = $input.first().json.output;
const originalMail = $('llegada Mail').first().json.originalTask;

if (!aiResponse ){
  circuitState.failureCount++;
  circuitState.lastFailureTime = Date.now();
  if (circuitState.failureCount >= FAILURE_THRESHOLD){

    circuitState.state = 'open';
    circuitState.openedAt = Date.now() ;
  }
  return [{ 
    json:{
      ...originalMail,
      error:true,
      _circuitStateToSave: circuitState 
    }
  }];
}

if (circuitState.state == 'half_open'){
  circuitState.succesCount++;
  if (circuitState.succesCount >=2){
    circuitState.failureCount=0;
    circuitState.openedAt = null;
  }
}

else if (circuitState.state === 'closed'){
  circuitState.failureCount = 0;
}

return[{
  json:{
    mail_clasification:{
      ...originalMail,
      clasificacion: aiResponse.clasificacion,
      confianza: aiResponse.confianza,
      justificacion: aiResponse.razon,
      nombre_remitente: aiResponse.nombre_remitente,
      tema: aiResponse.tema,
      clasificacion_method: 'ai_clasification'
    },
    palabras_clave_detectadas: aiResponse.palabras_clave_detectadas,
    classifiedAt: new Date().toISOString(),
    error:false,
    _circuitStateToSave: circuitState
  }
}];

// UseMailClassificationHeuristic v1.0
// Clasifica mails usando reglas heurísticas cuando AI no disponible
// --- TEMA + FECHA/HORA (para reuniones) ---
function extractFechaHora(texto) {
  const t = texto.toLowerCase();
  const patrones = [
    // Fechas numéricas: 15/03, 15-03, 15/03/2026
    /\b\d{1,2}[\/\-]\d{1,2}(?:[\/\-]\d{2,4})?\b/,
    // Días de la semana
    /\b(lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado|domingo)\b/,
    // Referencias relativas
    /\b(hoy|mañana|manana|pasado mañana|esta semana|la semana que viene|próxima semana|proxima semana)\b/,
    // Horarios: 10hs, 10:30, 10:30hs, 10h
    /\b\d{1,2}(?::\d{2})?(?:\s*hs?)\b/,
    // Rangos horarios: entre las 10 y las 12
    /entre las \d{1,2} y las \d{1,2}/
  ];

  for (const patron of patrones) {
    const match = t.match(patron);
    if (match) return match[0].trim();
  }
  return null;
}

function classifyMailHeuristic(mail, keywordsFromSheets) {

  // --- PALABRAS CLAVE BASE (fallback si Sheets está vacío) ---
  const baseKeywords = {
    SOLICITUD_DE_REUNION: [
      'reunión', 'reunion', 'llamada', 'videollamada', 'disponibilidad',
      'agendemos', 'coordinar', 'zoom', 'meet', 'teams', 'café', 'cafe',
      'nos vemos', 'podemos hablar', 'tenés un momento', 'tenes un momento'
    ],
    CONSULTA_GENERAL: [
      'consulta', 'pregunta', 'información', 'informacion', 'presupuesto',
      'plazo', 'entrega', 'precio', 'costo', 'ayuda', 'problema', 'error',
      'reclamo', 'feedback', 'estado', 'actualización', 'actualizacion'
    ]
  };

  const reunionKeywords = [
    ...baseKeywords.SOLICITUD_DE_REUNION,
    ...(keywordsFromSheets.SOLICITUD_DE_REUNION || [])
  ];
  const consultaKeywords = [
    ...baseKeywords.CONSULTA_GENERAL,
    ...(keywordsFromSheets.CONSULTA_GENERAL || [])
  ];

  // --- SCORING ---
  const text = (mail.asunto + ' ' + mail.cuerpo).toLowerCase();
  let scoreReunion = 0;
  let scoreConsulta = 0;

  reunionKeywords.forEach(kw => {
    if (text.includes(kw)) {
      const bonus = (keywordsFromSheets.SOLICITUD_DE_REUNION || []).includes(kw) ? 60 : 40;
      scoreReunion += bonus;
    }
  });
  consultaKeywords.forEach(kw => {
    if (text.includes(kw)) {
      const bonus = (keywordsFromSheets.CONSULTA_GENERAL || []).includes(kw) ? 60 : 40;
      scoreConsulta += bonus;
    }
  });

  // --- CLASIFICACIÓN ---
  let clasificacion = 'CONSULTA_GENERAL';
  let confianza = 'baja';
  const diff = Math.abs(scoreReunion - scoreConsulta);

  if (scoreReunion === 0 && scoreConsulta === 0) {
    confianza = 'baja';
  } else if (scoreReunion > scoreConsulta) {
    clasificacion = 'SOLICITUD_DE_REUNION';
    confianza = diff >= 60 ? 'alta' : diff >= 30 ? 'media' : 'baja';
  } else {
    clasificacion = 'CONSULTA_GENERAL';
    confianza = diff >= 60 ? 'alta' : diff >= 30 ? 'media' : 'baja';
  }


  // --- NOMBRE ---
  let nombre_remitente = null;
  const from = mail.remitente;
  if (from) {
    const conNombre = from.match(/^(.+?)\s*</);
    if (conNombre) {
      nombre_remitente = conNombre[1].replace(/"/g, '').trim();
    } else {
      const soloEmail = from.match(/([^@<\s]+)@/);
      if (soloEmail) {
        nombre_remitente = soloEmail[1]
          .replace(/[._-]/g, ' ')
          .split(' ')
          .map(w => w.charAt(0).toUpperCase() + w.slice(1))
          .join(' ');
      }
    }
  }

  // --- TEMA ---
  let tema = null;
  const stopWords = [
    're:', 'fwd:', 'fw:', 'consulta', 'pregunta', 'hola', 'buenos días',
    'buenas tardes', 'estimado', 'estimados', 'saludos', 'sobre', 'acerca',
    'de', 'la', 'el', 'los', 'las', 'un', 'una', 'por', 'para', 'con', 'del', 'al'
  ];
  const limpiar = (texto) => {
    let t = texto.toLowerCase();
    stopWords.forEach(sw => {
      t = t.replace(new RegExp(`\\b${sw}\\b`, 'gi'), '');
    });
    return t.replace(/\s+/g, ' ').trim();
  };

  if (mail.asunto && mail.asunto.trim().length > 3) {
    const candidato = limpiar(mail.asunto);
    if (candidato.length > 3) tema = candidato.split(' ').slice(0, 5).join(' ');
  }
  if (!tema && mail.cuerpo && mail.cuerpo.trim().length > 0) {
    const primeraLinea = mail.cuerpo.split('\n').find(l => l.trim().length > 10) || '';
    const candidato = limpiar(primeraLinea);
    if (candidato.length > 3) tema = candidato.split(' ').slice(0, 5).join(' ');
  }

  if (clasificacion === 'SOLICITUD_DE_REUNION') {
    const textoCompleto = mail.asunto + ' ' + mail.cuerpo;
    const fechaHora = extractFechaHora(textoCompleto);
    if (fechaHora) {
      tema = (tema || 'reunión') + ' — ' + fechaHora;
    }
  }

  return {
    clasificacion,
    confianza,
    razon: `Clasificación heurística (score reunión: ${scoreReunion} / consulta: ${scoreConsulta}). AI temporalmente no disponible.`,
    score_reunion: scoreReunion,
    score_consulta: scoreConsulta,
    method: 'heuristic_fallback',
    nombre_remitente,
    tema
  };
}

// --- INPUT ---
const datos = $('llegada Mail').first().json;

const mailForPrompt = {
  asunto: datos.Subject || '',
  cuerpo: datos.snippet || '',
  remitente: datos.From || ''
};

const keywordsFromSheets = { SOLICITUD_DE_REUNION: [], CONSULTA_GENERAL: [] };

const result = classifyMailHeuristic(mailForPrompt, keywordsFromSheets);

console.log(`⚠️ Usando fallback heurístico para mail: "${mailForPrompt.asunto}"`);

return [{
  json: {
    mail_clasification: {
      ...mailForPrompt,
      clasificacion: result.clasificacion,
      confianza: result.confianza,
      justificacion: result.razon,
      nombre_remitente: result.nombre_remitente,
      tema: result.tema,
      clasificacion_method: result.method
    },
    clasificacion_score_reunion: result.score_reunion,
    clasificacion_score_consulta: result.score_consulta,
    usedFallback: true,
    classifiedAt: new Date().toISOString()
  }
}];

const datos = $input.first().json.mail_clasification;

const mensaje= `¡Recibiste una nueva solicitud de reunión!\n-CONFIANZA: ${datos.confianza}${datos.confianza === 'baja' ? '(conviene revisar)' : ''}\n-MÉTODO DE CLASIFICACIÓN: ${datos.clasificacion_method.replace(/_/g, '-')}\n-NOMBRE: ${datos.nombre_remitente}\n-TEMA: ${datos.tema}`;

return [{
  json:{
    mensaje,
    datos
  }
}];

const data = $input.first().json;

// Confianza baja → no agregar nada
if (data.confianza === 'baja') {
  return [];
}

const palabras = data.palabras_clave_detectadas || [];
const clasificacion = data.clasificacion;

return [{
  json: {
    SOLICITUD_DE_REUNION: clasificacion === 'SOLICITUD_DE_REUNION' ? palabras : [],
    CONSULTA_GENERAL: clasificacion === 'CONSULTA_GENERAL' ? palabras : []
  }
}];
